import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

// Mixed verification data (data/archive2-source-verification/mixed-v1) is generated by
// archive/tools/build-archive2-catalog.mjs (run by tools/check-archive2-runtime.cjs) and is not committed.
// The layout it emits is chosen by archive/tools/archive2-mixed-verification-policy.json (default "v1": an
// already-deployed Worker cannot read the compact schema v2 until it is redeployed). This test covers both layouts:
// the one on disk (the policy default), and v1 and v2 built from the same rows with the builder's own codec, each
// through both loader plans (per-source and per-UID-bucket).

const require = createRequire(import.meta.url);
const canonical = require("../archive/archive2-canonical.js");
const core = require("../archive/archive2-core.js");
const { catalog } = require("./helpers/archive2-scope-harness.cjs");
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const codec = await import("../archive/tools/mixed-verification-codec.mjs");
const archiveDir = path.join(root, "archive");
const baseUrl = "https://archive.test/AP------/archive/";
const readText = (relative) => fs.readFileSync(path.join(archiveDir, relative), "utf8");
const sha256 = (value) => crypto.createHash("sha256").update(value).digest("hex");

const manifest = JSON.parse(readText("data/archive2-canonical-input-manifest.json"));
const sourceIndex = JSON.parse(readText("data/archive2-source-verification-index.json"));
assert.ok(sourceIndex.mixedLookup, "the source verification index must carry a mixed lookup");
const lookup = sourceIndex.mixedLookup;
const sourceFiles = sourceIndex.files.map((row) => row.sourceFile);

test("decodeMixedRows restores standard, escaped and explicit rows and rejects malformed tables", () => {
  const dict = ["COMMON_1", "고1"];
  const shapes = [["identityStatus", "courseFamilies", "note"], ["note"]];
  const resource = {
    dict,
    shapes,
    rows: [
      // standard source row: identity and record ids are implied
      ["qid_v1_" + "a".repeat(64), 1, "~1", 0, ["VERIFIED", ["~0"], "~~literal"], [], []],
      // explicit identity (null) and explicit record ids
      ["qid_v1_" + "b".repeat(64), 2, "~1", 1, ["plain"], [{ store: "s", L2: "~0" }], [],
        { identity: null, recordIds: { sourceOrdinal: 9 } }],
    ],
  };
  const rows = canonical.decodeMixedRows(resource, { kind: "source", sourceFile: "x/y.js" });
  assert.deepEqual(rows[0], {
    questionUid: "qid_v1_" + "a".repeat(64), sourceFile: "x/y.js", sourceOrdinal: 1, registeredGrade: "고1",
    identity: { questionUid: "qid_v1_" + "a".repeat(64), sourceArchiveFile: "x/y.js", sourceOrdinal: 1, status: "VERIFIED" },
    assignments: [], advancedAssignments: [],
    record: {
      sourceFile: "x/y.js", sourceOrdinal: 1, questionUid: "qid_v1_" + "a".repeat(64),
      identityStatus: "VERIFIED", courseFamilies: ["COMMON_1"], note: "~literal",
    },
  });
  assert.equal(rows[1].identity, null);
  assert.deepEqual(rows[1].record, { sourceOrdinal: 9, note: "plain" });
  assert.deepEqual(rows[1].assignments, [{ store: "s", L2: "COMMON_1" }]);

  // buckets index the shared source table; requested-only decoding stubs the other rows
  const bucket = { dict: [], shapes: [[]], rows: [
    ["qid_v1_" + "c".repeat(64), 1, 4, "x", 0, [], [], []],
    ["qid_v1_" + "d".repeat(64), 0, 7, "x", 0, [], [], []],
  ] };
  const stubbed = canonical.decodeMixedRows(bucket, {
    kind: "bucket", files: ["a.js", "b.js"], only: new Set(["qid_v1_" + "d".repeat(64)]),
  });
  assert.deepEqual(stubbed[0], { questionUid: "qid_v1_" + "c".repeat(64) });
  assert.equal(stubbed[1].sourceFile, "a.js");
  assert.equal(stubbed[1].record.sourceFile, "a.js");

  const malformed = [
    { ...resource, dict: [1] },
    { ...resource, shapes: [["ok", 3]] },
    { ...resource, rows: [["too", "short"]] },
    { ...resource, rows: [["qid_v1_" + "a".repeat(64), 1, "~z", 0, ["x", ["y"], "z"], [], []]] },
    { ...resource, rows: [["qid_v1_" + "a".repeat(64), 1, "~1", 5, ["x", ["y"], "z"], [], []]] },
    { ...resource, rows: [["qid_v1_" + "a".repeat(64), 1, "~1", 0, ["only one value"], [], []]] },
    { ...resource, rows: [["qid_v1_" + "a".repeat(64), 1.5, "~1", 0, ["x", ["y"], "z"], [], []]] },
    { ...resource, rows: [["qid_v1_" + "a".repeat(64), 1, "~01", 0, ["x", ["y"], "z"], [], []]] },
  ];
  for (const bad of malformed)
    assert.throws(
      () => canonical.decodeMixedRows(bad, { kind: "source", sourceFile: "x/y.js" }),
      (error) => error.code === "CANONICAL_INPUT_DIGEST_MISMATCH",
    );
  assert.throws(() => canonical.decodeMixedRows({ dict: [], shapes: [], rows: [] }, { kind: "bucket" }));
});

// ---- generated artifacts ----

const diskLayout = /-index-(v[12])$/.exec(lookup.schemaVersion)?.[1];
let loadedResources = null;
function loadAllResources() {
  if (loadedResources) return loadedResources;
  assert.ok(diskLayout, "the mixed lookup must declare a supported layout: " + lookup.schemaVersion);
  const files = lookup.files.map((row, index) => {
    const sourceFile = sourceFiles[index];
    const relative = "data/archive2-source-verification/mixed-v1/sources/" +
      sha256(sourceFile) + ".json";
    const text = readText(relative);
    assert.equal(sha256(text), row.sha256, relative);
    const resource = JSON.parse(text);
    assert.equal(resource.schemaVersion, "archive2-mixed-source-verification-" + diskLayout);
    const rows = diskLayout === "v2"
      ? canonical.decodeMixedRows(resource, { kind: "source", sourceFile })
      : resource.records;
    return { sourceFile, relative, resource, rows };
  });
  const buckets = lookup.uidBuckets.map((row) => {
    const text = readText(row.path);
    assert.equal(sha256(text), row.sha256, row.path);
    const resource = JSON.parse(text);
    assert.equal(resource.schemaVersion, "archive2-mixed-source-verification-uid-bucket-" + diskLayout);
    const rows = diskLayout === "v2"
      ? canonical.decodeMixedRows(resource, { kind: "bucket", files: sourceFiles })
      : resource.records;
    return { row, resource, rows };
  });
  loadedResources = { files, buckets };
  return loadedResources;
}

test("the emitted layout follows the policy file, which keeps schema v1 until the Worker is redeployed", () => {
  const policyPath = "archive/tools/archive2-mixed-verification-policy.json";
  const policy = JSON.parse(fs.readFileSync(path.join(root, policyPath), "utf8"));
  assert.equal(policy.schemaVersion, "ARCHIVE2_MIXED_VERIFICATION_POLICY_V1");
  assert.equal(codec.readMixedEmitSchema(root), policy.emitSchema);
  assert.equal(lookup.schemaVersion, "archive2-mixed-source-verification-index-" + policy.emitSchema);
  // Deliberate guard: switching to v2 is a reviewed decision that needs a Worker redeploy from a main with the v2
  // reader first (see policy.documentation). Whoever flips emitSchema must update this expectation in the same commit.
  assert.equal(policy.emitSchema, "v1", "emitSchema must stay v1 until the hand-deployed Worker has been redeployed");
  assert.ok(Array.isArray(policy.documentation.howToEnableV2) && policy.documentation.howToEnableV2.length >= 3);
});

test("the builder codec refuses unknown layouts and a malformed policy", () => {
  assert.throws(() => codec.buildMixedSourceShard({ schema: "v3", sourceFile: "a.js", sourceSha256: "", qCount: 0, rows: [] }));
  assert.throws(() => codec.buildMixedUidBucket({ schema: "v0", prefix: "0", rows: [], sourceFiles: [] }));
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "mixed-policy-"));
  try {
    fs.mkdirSync(path.join(tmp, "archive/tools"), { recursive: true });
    const target = path.join(tmp, "archive/tools/archive2-mixed-verification-policy.json");
    for (const bad of ["{", "{}", JSON.stringify({ schemaVersion: "ARCHIVE2_MIXED_VERIFICATION_POLICY_V1", emitSchema: "v3" })]) {
      fs.writeFileSync(target, bad);
      assert.throws(() => codec.readMixedEmitSchema(tmp), /Mixed verification policy/);
    }
    fs.writeFileSync(target, JSON.stringify({ schemaVersion: "ARCHIVE2_MIXED_VERIFICATION_POLICY_V1", emitSchema: "v2" }));
    assert.equal(codec.readMixedEmitSchema(tmp), "v2");
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

test("generated per-source shards and UID buckets carry identical rows that match the catalog", () => {
  const { files, buckets } = loadAllResources();
  const bySource = new Map();
  for (const file of files) for (const row of file.rows) bySource.set(row.questionUid, row);
  const byBucket = new Map();
  for (const bucket of buckets) for (const row of bucket.rows) byBucket.set(row.questionUid, row);
  assert.equal(bySource.size, byBucket.size);
  assert.ok(bySource.size > 20000, "the whole archive must be covered");
  for (const [uid, row] of bySource) assert.deepEqual(byBucket.get(uid), row, uid);

  const catalogByUid = new Map(catalog.records.filter((record) => /^qid_v1_[a-f0-9]{64}$/.test(record.questionUid || ""))
    .map((record) => [record.questionUid, record]));
  assert.equal(catalogByUid.size, bySource.size);
  for (const [uid, row] of bySource) {
    const record = catalogByUid.get(uid);
    assert.ok(record, uid);
    assert.equal(row.sourceFile, core.normalizeFile(record.sourceFile));
    assert.equal(row.sourceOrdinal, Number(record.sourceOrdinal));
    assert.equal(row.identity?.status, "VERIFIED");
    assert.equal(row.identity.sourceArchiveFile, row.sourceFile);
    for (const [key, value] of Object.entries(row.record)) {
      if (key === "sourceFile") assert.equal(value, row.sourceFile);
      else assert.deepEqual(value, JSON.parse(JSON.stringify(record[key])), uid + " " + key);
    }
    assert.deepEqual(row.assignments, JSON.parse(JSON.stringify(
      (catalog.canonicalAuthority.assignmentsByUid[uid] || []).map((assignment) => pickAssignment(assignment)),
    )), uid + " assignments");
  }
});

function pickAssignment(assignment) {
  const fields = [
    "store", "questionUid", "sourceFile", "sourceOrdinal", "grade", "curriculumKey",
    "courseKey", "L1", "L2", "problemTypeKey", "templateKey", "standardUnitKey",
    "subUnitKey", "sourceFingerprint", "assignmentFingerprint", "approvalStatus",
    "taxonomyVersion", "l4Disposition",
  ];
  const row = Object.fromEntries(fields.filter((field) => Object.hasOwn(assignment, field)).map((field) => [field, assignment[field]]));
  if (assignment.reviewEvidence && typeof assignment.reviewEvidence === "object")
    row.reviewEvidence = Object.fromEntries(
      ["status", "reference", "sha256", "runtimeEvidenceReference", "runtimeEvidenceSha"]
        .filter((field) => Object.hasOwn(assignment.reviewEvidence, field))
        .map((field) => [field, assignment.reviewEvidence[field]]),
    );
  return row;
}

function makeFetcher(overrides = new Map()) {
  const requests = [];
  const fetcher = async (input) => {
    const pathname = decodeURIComponent(new URL(String(input)).pathname);
    const relative = pathname.replace(/^\/AP------\/archive\//, "");
    requests.push(relative);
    if (overrides.has(relative)) return new Response(overrides.get(relative), { status: 200 });
    const file = path.join(archiveDir, relative);
    if (!file.startsWith(archiveDir) || !fs.existsSync(file)) return new Response("Not found", { status: 404 });
    return new Response(fs.readFileSync(file), { status: 200 });
  };
  return { fetcher, requests };
}

function pickRequests(rows, perSource) {
  const bySource = new Map();
  for (const row of rows) {
    if (!bySource.has(row.sourceFile)) bySource.set(row.sourceFile, []);
    bySource.get(row.sourceFile).push(row);
  }
  const picked = [];
  for (const list of bySource.values())
    picked.push(...list.slice(0, perSource));
  return picked;
}

// Rebuild the whole mixed data set in the requested layout from the decoded rows with the builder's own codec and
// return it as a fetch override map, together with a consistent source index and canonical manifest.
async function layoutOverrides(schema) {
  const { files, buckets } = loadAllResources();
  const overrides = new Map();
  const nextLookup = JSON.parse(JSON.stringify(lookup));
  nextLookup.schemaVersion = codec.mixedIndexSchemaVersion(schema);
  files.forEach((file, index) => {
    const shard = codec.buildMixedSourceShard({
      schema, sourceFile: file.sourceFile, sourceSha256: file.resource.sourceSha256, qCount: file.resource.qCount, rows: file.rows,
    });
    const body = JSON.stringify(shard) + "\n";
    overrides.set(file.relative, body);
    nextLookup.files[index] = {
      sourceIndex: index, sha256: sha256(body), byteLength: Buffer.byteLength(body), recordCount: file.rows.length,
    };
  });
  const context = buckets.find((bucket) => bucket.row.prefix === "f").resource.context;
  buckets.forEach((bucket, index) => {
    const built = codec.buildMixedUidBucket({
      schema, prefix: bucket.row.prefix, context, rows: bucket.rows, sourceFiles,
    });
    const body = JSON.stringify(built) + "\n";
    overrides.set(bucket.row.path, body);
    nextLookup.uidBuckets[index] = { ...bucket.row, sha256: sha256(body), byteLength: Buffer.byteLength(body) };
  });
  const nextIndexText = JSON.stringify({ ...sourceIndex, mixedLookup: nextLookup }) + "\n";
  const nextManifest = JSON.parse(JSON.stringify(manifest));
  nextManifest.files.find((row) => row.path === canonical.SOURCE_VERIFICATION_INDEX_PATH).sha256 = sha256(nextIndexText);
  nextManifest.projectionVersion = await canonical.computeProjectionVersion(nextManifest.files, nextManifest.resolverVersion);
  overrides.set("data/archive2-source-verification-index.json", nextIndexText);
  overrides.set("data/archive2-canonical-input-manifest.json", JSON.stringify(nextManifest) + "\n");
  return { overrides, manifest: nextManifest, lookup: nextLookup };
}

// plan(layout) -> loader checks used for the on-disk layout and for both rebuilt layouts.
async function assertLoaderPlans({ overrides, manifest: usedManifest, layout }) {
  const { files } = loadAllResources();
  const everyRow = files.flatMap((file) => file.rows);
  const expected = new Map(everyRow.map((row) => [row.questionUid, row]));
  const toRequests = (rows) => rows.map((row) => ({ questionUid: row.questionUid, sourceFile: row.sourceFile, sourceOrdinal: row.sourceOrdinal }));

  // few sources -> per-source plan
  const few = pickRequests(everyRow.filter((row) => row.sourceFile === sourceFiles[3] || row.sourceFile === sourceFiles[40]), 2);
  const fewEnv = makeFetcher(overrides);
  const fewResult = await canonical.loadMixedVerificationRecords(fewEnv.fetcher, baseUrl, usedManifest.projectionVersion, toRequests(few));
  assert.equal(fewResult.legacyManifest, false, layout);
  assert.equal(fewResult.records.length, few.length, layout);
  for (const row of fewResult.records) assert.deepEqual(row, expected.get(row.questionUid), layout);
  assert.ok(fewEnv.requests.some((request) => request.includes("/mixed-v1/sources/")), layout);
  assert.equal(fewEnv.requests.some((request) => request.includes("/mixed-v1/uid-buckets/")), false, layout);

  // more than 15 distinct sources -> UID-bucket plan
  const wide = pickRequests(everyRow.filter((row) => sourceFiles.indexOf(row.sourceFile) % 40 === 0), 1).slice(0, 20);
  assert.ok(new Set(wide.map((row) => row.sourceFile)).size > 15);
  const wideEnv = makeFetcher(overrides);
  const wideResult = await canonical.loadMixedVerificationRecords(wideEnv.fetcher, baseUrl, usedManifest.projectionVersion, toRequests(wide));
  assert.equal(wideResult.records.length, wide.length, layout);
  for (const row of wideResult.records) assert.deepEqual(row, expected.get(row.questionUid), layout);
  assert.ok(wideEnv.requests.some((request) => request.includes("/mixed-v1/uid-buckets/")), layout);
  assert.equal(wideEnv.requests.some((request) => request.includes("/mixed-v1/sources/")), false, layout);
  assert.ok(wideResult.authority && wideResult.authority.taxonomyVersion, layout);

  // a UID claimed under another source resolves to nothing
  const first = files[0].rows[0], other = files[5];
  const env = makeFetcher(overrides);
  const claimed = await canonical.loadMixedVerificationRecords(env.fetcher, baseUrl, usedManifest.projectionVersion, [
    { questionUid: first.questionUid, sourceFile: other.sourceFile, sourceOrdinal: first.sourceOrdinal },
  ]);
  assert.deepEqual(claimed.records, [], layout);
}

test("the loader reads the layout that is on disk (the policy default) through both loader plans", async () => {
  await assertLoaderPlans({ overrides: new Map(), manifest, layout: "disk:" + diskLayout });
});

test("schema v1 rebuilt with the builder codec loads through both plans, so a Worker deployed before v2 keeps working", async () => {
  const rebuilt = await layoutOverrides("v1");
  assert.equal(rebuilt.lookup.schemaVersion, "archive2-mixed-source-verification-index-v1");
  await assertLoaderPlans({ ...rebuilt, layout: "v1" });
});

test("schema v2 (enabled by the policy switch) loads through both plans with identical rows and is smaller than v1", async () => {
  const v2 = await layoutOverrides("v2");
  assert.equal(v2.lookup.schemaVersion, "archive2-mixed-source-verification-index-v2");
  await assertLoaderPlans({ ...v2, layout: "v2" });
  const v1 = await layoutOverrides("v1");
  const bytes = (map) => [...map.entries()]
    .filter(([key]) => key.includes("/mixed-v1/"))
    .reduce((sum, [, body]) => sum + Buffer.byteLength(body), 0);
  assert.ok(bytes(v2.overrides) < bytes(v1.overrides) * 0.6, "the compact layout must stay clearly smaller than v1");
});
